#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

(* [comment removed for export] *)
Definition art_free3P_out (M0 M7 M' : word -> option byte) (S t p q16 qr l2 blk b1 parr mb ms : Z) (bl : list (Z * Z)) (idx : nat) (kb : nat) (D : list (list Z)) : Prop :=
  mem_grows M0 M7
  /\ art_agree (art_free3_W S t p q16 qr l2 blk) M0 M7
  /\ DInvK l2 blk kb D M7
  /\ cellA M7 (p - 16) 4 (3 + 256 * b1)
  /\ cellA M7 0x1d5b88 4 1 /\ (forall k, 0 <= k < 2 ^ 15 -> cellA M7 (0x147308 + 8 * k) 8 0)
  /\ cellA M7 (t + 3168) 1 0
  /\ art_agree (art_cbr_sec_fp (S - 2208) t parr (Z.of_nat idx) (fst (nth (length bl - 1) bl (0, 0))) mb ms) M7 M'
  /\ (forall x : word, mb <= U x < mb + ms -> M' x = None)
  /\ (forall x : word, SB + mb / 8 <= U x < SB + mb / 8 + ms / 8 -> M' x = Some (Z_to_bv 8 0))
  /\ (forall a k, 0 <= a -> a + k < 2 ^ 64 -> apart mb ms a k -> wrA M7 a k -> wrA M' a k)
  /\ art_sec_cells M' parr (art_swap_remove (0, 0) idx bl).

Section Spec.
Variable EVOK : list aev -> aev -> Prop.
Variable GR : list aev -> (word -> option byte) -> Z -> Z -> Prop.
Variable Lz : HeapIfaceA.asan_layout.
Variable arz : HeapIfaceA.asan_run.
Context {fx : PropExec.FPState}.

#[using="Type"] Theorem art_free3P :
  forall (Q : list aev -> machine_state -> Prop) (log : list aev) regs (M0 rom : word -> option byte) (raw0 : word)
         (S HI p q16 n qr b1 tp key tsd ctx t spb ris qs km l2 blk top bot L B wB cntB bszB bytes : Z) (kb : nat) (Dz : list (list Z)) (Kz : list Z) (ia inited : bool) (cl : art_cls) (parr mb ms f1 f2 : Z) (bl : list (Z * Z)) (idx : nat),
    let c := t + 80 in
    let ca := t + 208 in
    let b := spb + 24 * 2 ^ 32 + 16 * art_ca_cptr 24 cl in
